/* ==========================================================================
   Layered UI Design Tokens & Theme Systems
   ========================================================================== */

:root,
[data-theme="classic"] {
    /* Theme identity */
    --theme-name: "classic";

    /* Primitive color ramps. Component styles consume semantic aliases below
       so the raw scale can evolve without coupling components to a step. */
    --palette-neutral-50: #f7f6f2;
    --palette-neutral-100: #e9e7df;
    --palette-neutral-200: #d1cec4;
    --palette-neutral-300: #b9b3a6;
    --palette-neutral-400: #96938c;
    --palette-neutral-500: #77787a;
    --palette-neutral-600: #626365;
    --palette-neutral-700: #525355;
    --palette-neutral-800: #38393b;
    --palette-neutral-900: #292a2c;
    --palette-neutral-950: #1a1b1d;

    --palette-copper-50: #fff5eb;
    --palette-copper-100: #f7e1cf;
    --palette-copper-200: #ecc7a7;
    --palette-copper-300: #dca378;
    --palette-copper-400: #c47c45;
    --palette-copper-500: #a96539;
    --palette-copper-600: #7d4d31;
    --palette-copper-700: #6b432b;
    --palette-copper-800: #5c3c28;
    --palette-copper-900: #422a1f;
    --palette-copper-950: #261713;

    --palette-green-50: #f5f8ec;
    --palette-green-100: #e6edd3;
    --palette-green-200: #cfdda9;
    --palette-green-300: #afc57d;
    --palette-green-400: #8da85a;
    --palette-green-500: #6f8c48;
    --palette-green-600: #566f3b;
    --palette-green-700: #455b32;
    --palette-green-800: #35462b;
    --palette-green-900: #273521;
    --palette-green-950: #161f14;

    --palette-gold-50: #fff8e6;
    --palette-gold-100: #fbeac0;
    --palette-gold-200: #f2d68d;
    --palette-gold-300: #e4b85f;
    --palette-gold-400: #d1a04a;
    --palette-gold-500: #b98739;
    --palette-gold-600: #92682f;
    --palette-gold-700: #735326;
    --palette-gold-800: #5b421f;
    --palette-gold-900: #3d2c17;
    --palette-gold-950: #24180c;

    --palette-red-50: #ffffff;
    --palette-red-100: #ffdede;
    --palette-red-200: #f8baba;
    --palette-red-300: #f08d8d;
    --palette-red-400: #e96b6b;
    --palette-red-500: #e55353;
    --palette-red-600: #c63f3f;
    --palette-red-700: #9f3333;
    --palette-red-800: #7d2c2c;
    --palette-red-900: #522020;
    --palette-red-950: #301010;

    /* Page surfaces */
    --color-canvas: #353638;
    --color-canvas-deep: #292a2c;
    --color-text: #f3ebd6;
    --color-text-title: #f3ebd6;
    --color-text-emphasis: #ffffff;
    --color-text-muted: #b9b3a6;

    /* Shared component casing */
    --control-shell-top: #5b504a;
    --control-shell-bottom: #463d39;
    --control-shell-border: #121212;
    --control-trench: #1a130f;

    /* Component recessed surfaces & casings */
    --input-casing-top: #483f3a;
    --input-casing-bottom: #362e2a;
    --input-surface-bg-top: #18191b;
    --input-surface-bg-bottom: #1e1f21;
    --panel-surface-bg-top: #2b2c2e;
    --panel-surface-bg-bottom: #222325;

    /* Focus & Status */
    --control-focus: var(--palette-gold-300);
    --control-error: var(--palette-red-500);
    --control-error-text: var(--palette-red-50);

    /* System Tones: Copper, Green, Gold, Neutral */
    --tone-copper-light: var(--palette-copper-400);
    --tone-copper-mid: var(--palette-copper-600);
    --tone-copper-dark: var(--palette-copper-800);
    --tone-copper-text: #f3ebd6;

    --tone-green-light: var(--palette-green-400);
    --tone-green-mid: var(--palette-green-600);
    --tone-green-dark: var(--palette-green-800);
    --tone-green-text: #f3ebd6;

    --tone-gold-light: var(--palette-gold-400);
    --tone-gold-mid: var(--palette-gold-600);
    --tone-gold-dark: var(--palette-gold-800);
    --tone-gold-text: #f3ebd6;

    --tone-neutral-light: var(--palette-neutral-500);
    --tone-neutral-mid: var(--palette-neutral-700);
    --tone-neutral-dark: var(--palette-neutral-800);
    --tone-neutral-text: #f3ebd6;

    --tone-soft-accent: var(--palette-copper-400);
}

[data-theme="field"] {
    /* Theme identity: Field Equipment / Mid-Century Hardware */
    --theme-name: "field";

    /* Field theme preserves the same ramp API while shifting the material
       character toward oxidized metal, canvas, brass, and muted signals. */
    --palette-neutral-50: #f4f5f6;
    --palette-neutral-100: #e4e6ea;
    --palette-neutral-200: #cfd3da;
    --palette-neutral-300: #b2b8c4;
    --palette-neutral-400: #9fa5b4;
    --palette-neutral-500: #79727d;
    --palette-neutral-600: #626670;
    --palette-neutral-700: #4c4f57;
    --palette-neutral-800: #383b42;
    --palette-neutral-900: #2c2e30;
    --palette-neutral-950: #1e2022;

    --palette-copper-50: #fbf7f2;
    --palette-copper-100: #efe4d9;
    --palette-copper-200: #dcc9b6;
    --palette-copper-300: #c9ac8f;
    --palette-copper-400: #b08a6e;
    --palette-copper-500: #967254;
    --palette-copper-600: #795940;
    --palette-copper-700: #624632;
    --palette-copper-800: #543c2b;
    --palette-copper-900: #39271d;
    --palette-copper-950: #211610;

    --palette-green-50: #eef5f2;
    --palette-green-100: #d7e8e2;
    --palette-green-200: #b1d1c7;
    --palette-green-300: #7eaa9d;
    --palette-green-400: #4c7d71;
    --palette-green-500: #3c6d62;
    --palette-green-600: #305e53;
    --palette-green-700: #264d45;
    --palette-green-800: #1a3831;
    --palette-green-900: #112923;
    --palette-green-950: #091813;

    --palette-gold-50: #fff8ee;
    --palette-gold-100: #f9e8d1;
    --palette-gold-200: #f3d2aa;
    --palette-gold-300: #e9bf8d;
    --palette-gold-400: #d9a96f;
    --palette-gold-500: #c29158;
    --palette-gold-600: #a88050;
    --palette-gold-700: #826039;
    --palette-gold-800: #5c4223;
    --palette-gold-900: #3d2b17;
    --palette-gold-950: #24180c;

    --palette-red-50: #fbf4f5;
    --palette-red-100: #eedfe1;
    --palette-red-200: #ddc4c7;
    --palette-red-300: #c5a2ab;
    --palette-red-400: #bd7c85;
    --palette-red-500: #b0636c;
    --palette-red-600: #9c4f59;
    --palette-red-700: #7f3e47;
    --palette-red-800: #63323a;
    --palette-red-900: #422329;
    --palette-red-950: #271216;

    /* Palette mapping reference (comments only):
       - Canvas: Dorkwood #3d3f42
       - Primary text: Sindis Poop #cccdc2
       - Warm/High-emphasis text & Title: Dope #dbd1b3
       - Muted text: Caring Tan #aba6aa
       - Structural Casing: Clardic Fug #707154 / Catbabel #615d44
       - Green tone: Grade Bat #305e53
       - Copper tone: Sand Dan #c9ac8f / Sink #b08a6e
       - Gold tone: Stargoon #e9bf8d / Burble Simp #e2b584
       - Neutral tone: Flower #b2b8c4 / Ronching Blue #79727d
       - Error: Grass Bat #b0636c (accent) / Bank Butt #ddc4c7 (text)
       - Soft accent: Stanky Bean #c5a2ab
       - Intentionally unused in runtime CSS: Bunflow (#beae9b), Stummy Beige (#d8c8b9), Light Of Blast (#af9693), Testing (#9c656a), Stoner Blue (#98a59f), Turdly (#bea474)
    */

    /* Page surfaces */
    --color-canvas: #3d3f42; /* Dorkwood */
    --color-canvas-deep: #2c2e30; /* Dark derived Dorkwood */
    --color-text: #cccdc2; /* Sindis Poop */
    --color-text-title: #dbd1b3; /* Dope (warm heading warmth) */
    --color-text-emphasis: #dbd1b3; /* Dope */
    --color-text-muted: #aba6aa; /* Caring Tan */

    /* Shared component casing */
    --control-shell-top: #707154; /* Clardic Fug */
    --control-shell-bottom: #615d44; /* Catbabel */
    --control-shell-border: #1e2017;
    --control-trench: #181912;

    /* Component recessed surfaces & casings */
    --input-casing-top: #55573e; /* Muted Clardic Fug / Catbabel */
    --input-casing-bottom: #43442f;
    --input-surface-bg-top: #212224; /* Recessed dark Dorkwood derivative */
    --input-surface-bg-bottom: #28292c;
    --panel-surface-bg-top: #2d2e31;
    --panel-surface-bg-bottom: #242527;

    /* Focus & Status */
    --control-focus: var(--palette-gold-300); /* Stargoon focus */
    --control-error: var(--palette-red-500); /* Grass Bat */
    --control-error-text: var(--palette-red-200); /* Bank Butt */

    /* System Tones & Per-Tone Button Text */
    --tone-copper-light: var(--palette-copper-300); /* Sand Dan */
    --tone-copper-mid: var(--palette-copper-500); /* Darkened Sink for depth */
    --tone-copper-dark: var(--palette-copper-800); /* Rich deep copper */
    --tone-copper-text: #1e2022; /* Dark Dorkwood text for high contrast on pale face */

    --tone-green-light: var(--palette-green-400);
    --tone-green-mid: var(--palette-green-600); /* Grade Bat */
    --tone-green-dark: var(--palette-green-800); /* Deep forest green */
    --tone-green-text: #dbd1b3; /* Dope (warm light text on green) */

    --tone-gold-light: var(--palette-gold-300); /* Stargoon */
    --tone-gold-mid: var(--palette-gold-600); /* Darkened gold mid for depth */
    --tone-gold-dark: var(--palette-gold-800); /* Deep rich gold */
    --tone-gold-text: #1e2022; /* Dark Dorkwood text for high contrast on pale face */

    --tone-neutral-light: var(--palette-neutral-400); /* Subdued slate light */
    --tone-neutral-mid: var(--palette-neutral-600); /* Slate neutral mid for depth */
    --tone-neutral-dark: var(--palette-neutral-800); /* Deep slate dark */
    --tone-neutral-text: #1e2022; /* Dark Dorkwood text for high contrast on pale face */

    --tone-soft-accent: var(--palette-red-300); /* Stanky Bean */
}

:root {
    /* Shape & Physics Tokens (preserved identically across themes) */
    --control-radius-outer: 12px;
    --control-radius-inner: 8px;
    --control-shell-depth: 4px;

    /* Motion Tokens */
    --duration-fast: 100ms;
    --duration-normal: 160ms;
    --ease-control: ease;

    /* Shadows */
    --shadow-control:
        0 6px 12px rgb(0 0 0 / 40%),
        inset 0 1px rgb(255 255 255 / 8%);

    --shadow-control-hover:
        0 8px 16px rgb(0 0 0 / 45%),
        inset 0 1px rgb(255 255 255 / 9%);

    --shadow-control-pressed:
        0 2px 4px rgb(0 0 0 / 55%);

    /* Overlay Stack — semantic z-index layers, shared across overlay
       components (Dialog, Popover/Dropdown Menu/Combobox, Toast, Tooltip).
       Ordered so a later-opening, higher-priority layer always clears an
       earlier one: tooltips can annotate controls inside dialogs, popovers,
       or toasts, so tooltip stays topmost. Popover, Dropdown Menu, and
       Combobox share `--layered-z-popover` — all three are anchored,
       non-modal-by-default overlays with no ordering requirement between
       them. */
    --layered-z-dialog-overlay: 1000;
    --layered-z-dialog-content: 1010;
    --layered-z-popover: 2000;
    --layered-z-toast: 3000;
    --layered-z-tooltip: 4000;
}
